import React from 'react';
import { Container, Row, Col, Card } from 'react-bootstrap';

const About = () => {
  return (
    <Container className="my-5">
      <h2 className="text-center mb-4">About Us</h2>
      <Row className="justify-content-center">
        <Col md={8}>
          <Card className="shadow-sm border-0">
            <Card.Body>
              <p>
                Welcome to <strong>Event Manager</strong>, your one-stop platform for discovering and managing exciting events. Our goal is to connect event organizers and participants in a seamless, user-friendly way. 
              </p>
              <p>
                Whether you’re looking for conferences, workshops, or entertainment events, we’ve got you covered. Users can easily browse upcoming events, register, and track their participation. Meanwhile, event organizers can manage their events effortlessly.
              </p>
              <p>
                We are committed to providing a reliable and vibrant experience for all event enthusiasts. Join us and make your event journey more exciting!
              </p>
            </Card.Body>
          </Card>
        </Col>
      </Row>
    </Container>
  );
};

export default About;
